import{_ as s,o as i,c as a,ag as t}from"./chunks/framework.C9sp7nFj.js";const d=JSON.parse('{"title":"Server key management","description":"","frontmatter":{},"headers":[],"relativePath":"guide/server-key-management.md","filePath":"guide/server-key-management.md","lastUpdated":1778915731000}'),n={name:"guide/server-key-management.md"};function r(l,e,o,h,p,k){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="server-key-management" tabindex="-1">Server key management <a class="header-anchor" href="#server-key-management" aria-label="Permalink to &quot;Server key management&quot;">​</a></h1><p>This guide walks through every operational scenario for the server-side at-rest encryption key. For the cryptographic background see <a href="./encryption">Encryption</a>; this page is the runbook.</p><h2 id="first-start-fresh-install" tabindex="-1">First start (fresh install) <a class="header-anchor" href="#first-start-fresh-install" aria-label="Permalink to &quot;First start (fresh install)&quot;">​</a></h2><p>At-rest encryption is <strong>opt-in</strong>. A new install runs without it until an administrator turns it on.</p><ol><li>Start pika. The process logs <code>server started; encryption not yet enabled</code> and serves every request normally.</li><li>Open the web UI and complete the standard first-run admin account setup.</li><li>Configure users, mounts, hooks, externals as needed — these all work in plaintext-at-rest mode.</li><li>When you&#39;re ready to turn on encryption, navigate to <strong>Settings → Server encryption key → Enable encryption</strong>.</li><li>Choose a strong passphrase. Save it in your password manager BEFORE clicking Enable — there is no recovery path.</li><li>Confirm the passphrase. The form posts to <code>POST /api/v1/key/initialize</code> (authenticated, requires <code>settings.manage</code>); the server writes a verifier record into the settings table, re-seals existing sensitive settings under the new key, and stays unlocked for the rest of the process lifetime.</li></ol><p>From here, every subsequent restart enters the locked state.</p><h3 id="cli-curl-variant" tabindex="-1">CLI / curl variant <a class="header-anchor" href="#cli-curl-variant" aria-label="Permalink to &quot;CLI / curl variant&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Cookie: pika_session=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SESSION</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;key&quot;:&quot;correct-horse-battery-staple&quot;}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  http://localhost:8080/api/v1/key/initialize</span></span></code></pre></div><p>The endpoint requires an authenticated session OR a token carrying <code>settings.manage</code>. <code>$SESSION</code> is the cookie value from <code>/login/password</code>.</p><h2 id="every-restart-unlock" tabindex="-1">Every-restart unlock <a class="header-anchor" href="#every-restart-unlock" aria-label="Permalink to &quot;Every-restart unlock&quot;">​</a></h2><p>Pika starts in the <strong>locked</strong> state on every restart. Until unlocked:</p><ul><li><code>/api/v1/info</code>, <code>/healthz</code>, <code>/login/*</code>, <code>/logout</code>, <code>/api/v1/me/*</code>, and <code>/api/v1/key/*</code> continue to work.</li><li>Every other request returns <code>503</code> with <code>X-Pika-Locked: true</code>.</li><li>The web UI&#39;s axios layer detects the header and renders the unlock screen automatically.</li></ul><p>Steps:</p><ol><li>Open the web UI. The unlock screen appears.</li><li>Paste the server key.</li><li>Click <strong>Unlock</strong>. The form posts to <code>POST /api/v1/key/unlock</code>.</li><li>Wrong key → 403 with a &quot;wrong key&quot; toast; the verifier protects against silent corruption.</li></ol><p>CLI variant:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Cookie: pika_session=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SESSION</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;key&quot;:&quot;correct-horse-battery-staple&quot;}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  http://localhost:8080/api/v1/key/unlock</span></span></code></pre></div><h2 id="status-check" tabindex="-1">Status check <a class="header-anchor" href="#status-check" aria-label="Permalink to &quot;Status check&quot;">​</a></h2><p>Always available, no auth required:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/api/v1/key/status</span></span></code></pre></div><p>Response:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;initialized&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;unlocked&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li><code>initialized: false</code> → the verifier record doesn&#39;t exist yet (fresh install).</li><li><code>unlocked: false</code> → server is locked; an admin must unlock.</li><li>Both <code>true</code> → server is online and serving normal traffic.</li></ul><h2 id="rotation" tabindex="-1">Rotation <a class="header-anchor" href="#rotation" aria-label="Permalink to &quot;Rotation&quot;">​</a></h2><p>When and why to rotate:</p><ul><li>Suspected key compromise.</li><li>Periodic rotation per your security policy.</li><li>Operator handover.</li></ul><p>Procedure (web UI):</p><ol><li>Sign in as a superadmin.</li><li><strong>Settings → Security → Server encryption key</strong>.</li><li>Enter the current key, the new key, and confirm the new key.</li><li>Save the new key in your password manager BEFORE clicking Rotate.</li><li>Click <strong>Rotate server key</strong>. The flow: <ol><li>Server validates the current key against the verifier.</li><li>Reads every encrypted blob through the current key.</li><li>Re-encrypts the verifier with the new key and installs the new key as live.</li><li>Re-writes the secret blobs through the new key.</li></ol></li><li>The next server restart will require the NEW key.</li></ol><p>CLI variant:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Cookie: pika_session=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SESSION</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;current_key&quot;:&quot;old&quot;,&quot;new_key&quot;:&quot;new&quot;}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  http://localhost:8080/api/v1/key/rotate</span></span></code></pre></div><h3 id="failure-modes-during-rotation" tabindex="-1">Failure modes during rotation <a class="header-anchor" href="#failure-modes-during-rotation" aria-label="Permalink to &quot;Failure modes during rotation&quot;">​</a></h3><p>If step 4 (re-write secrets) fails after step 3 (verifier swap), the server is in a partial state: the verifier matches the new key but a settings row may still hold old-key ciphertext. Recovery:</p><ul><li>Retry rotation using the NEW key as both <code>current_key</code> and the re-typed new key. The verifier accepts the new key, and the re-write step runs again. This is safe: the settings wrapper re-extracts secrets every time, so re-running puts everything on the new key.</li></ul><p>If the recovery rotation also fails:</p><ul><li>Restart the server, unlock with the new key, and inspect the settings row. Any secret slot that decrypts as garbage was lost in the half-rotation; restore from a recent backup taken under the new key (see Backups in <a href="./encryption">Encryption</a>).</li></ul><h2 id="manual-lock" tabindex="-1">Manual lock <a class="header-anchor" href="#manual-lock" aria-label="Permalink to &quot;Manual lock&quot;">​</a></h2><p>You can lock the server without restarting it. Useful for:</p><ul><li>Rotation rehearsals on a non-production environment.</li><li>&quot;I&#39;m stepping away from this terminal&quot; if you&#39;re worried about a shoulder-surfer.</li><li>Forcing every active user back through unlock when an operator leaves the company.</li></ul><p>Web UI: <strong>Settings → Security → Server encryption key → Lock the server now</strong>.</p><p>CLI:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Cookie: pika_session=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$SESSION</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  http://localhost:8080/api/v1/key/lock</span></span></code></pre></div><p>After lock, every non-allowlisted request returns 503; the web UI&#39;s axios interceptor flips immediately to the unlock screen for all open browser tabs the next time they make any request.</p><h2 id="disaster-scenarios" tabindex="-1">Disaster scenarios <a class="header-anchor" href="#disaster-scenarios" aria-label="Permalink to &quot;Disaster scenarios&quot;">​</a></h2><h3 id="lost-key-no-backup" tabindex="-1">Lost key, no backup <a class="header-anchor" href="#lost-key-no-backup" aria-label="Permalink to &quot;Lost key, no backup&quot;">​</a></h3><p>Encrypted columns are unrecoverable. To restore service you must:</p><ol><li>Wipe the database (<code>PIKA_STORAGE_BW_PATH</code> directory).</li><li>Start fresh. The Initialize flow will appear.</li><li>Re-create users, mounts, hooks, externals from scratch.</li></ol><p>User accounts and sessions are NOT in the encrypted set, but they live in the same Badger directory and a wipe loses them too.</p><h3 id="lost-key-have-a-backup" tabindex="-1">Lost key, have a backup <a class="header-anchor" href="#lost-key-have-a-backup" aria-label="Permalink to &quot;Lost key, have a backup&quot;">​</a></h3><ol><li>Locate a backup taken when you still had the key.</li><li>Restore the backup into a fresh server.</li><li>Unlock with the key that was active when the backup was taken.</li><li>Once unlocked, rotate to a new key you control.</li></ol><p>If you don&#39;t have the original key for the backup either, the backup is also unrecoverable — the export is the on-disk ciphertext as-is. Plan accordingly: backup-and-key-archive should live in the same secure store.</p><h3 id="operator-handover" tabindex="-1">Operator handover <a class="header-anchor" href="#operator-handover" aria-label="Permalink to &quot;Operator handover&quot;">​</a></h3><ol><li>Outgoing operator initiates rotation, picks the new key themselves, hands off through the org&#39;s normal credential- transfer process.</li><li>Incoming operator confirms unlock works with the new key on the next restart cycle (e.g. roll one pod in a multi-replica deployment).</li><li>Outgoing operator&#39;s password manager entry for the old key can be deleted.</li></ol>`,51)])])}const u=s(n,[["render",r]]);export{d as __pageData,u as default};
